import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Pr } from '../types'

const POLL_MS = 60_000
const FIELDS =
  'number,title,reviewDecision,latestReviews,statusCheckRollup,mergeable,comments,reviews'
const PASSED = ['SUCCESS', 'NEUTRAL', 'SKIPPED']
const WAITING = ['', 'PENDING', 'EXPECTED']
const REVIEW: Record<string, [string, string]> = {
  APPROVED: ['✓ Approved', 'green'],
  CHANGES_REQUESTED: ['✗ Changes requested', 'red'],
  REVIEW_REQUIRED: ['● Review pending', 'yellow'],
}

const pr = atom({ plugin: 'pr-tracker', key: 'pr' } as const, null)

type Check = { conclusion?: string; state?: string }
type Raw = {
  number: number
  title: string
  reviewDecision: string
  mergeable: string
  latestReviews: { state: string }[]
  statusCheckRollup: Check[] | null
  comments: unknown[]
  reviews: unknown[]
}

const summarize = (raw: Raw): Pr => {
  // ponytail: counts every check, not only required ones; `gh pr checks --required` if that matters
  const verdicts = (raw.statusCheckRollup ?? []).map(c => c.conclusion || c.state || '')

  return {
    number: raw.number,
    title: raw.title,
    review: raw.reviewDecision,
    approvals: raw.latestReviews.filter(r => r.state === 'APPROVED').length,
    pass: verdicts.filter(v => PASSED.includes(v)).length,
    pending: verdicts.filter(v => WAITING.includes(v)).length,
    fail: verdicts.filter(v => !PASSED.includes(v) && !WAITING.includes(v)).length,
    hasConflict: raw.mergeable === 'CONFLICTING',
    comments: raw.comments.length + raw.reviews.length,
  }
}

// No PR for this branch, no repo, no gh, not logged in: all read as "nothing to show".
const fetchPr = async ($: EngineInterface): Promise<Pr | null> => {
  try {
    const { exitCode, stdout } = await $.process.run(['gh', 'pr', 'view', '--json', FIELDS])

    return exitCode === 0 ? summarize(JSON.parse(stdout) as Raw) : null
  } catch {
    return null
  }
}

const poll = async ($: EngineInterface) => {
  const now = await fetchPr($)
  const before = await read($, pr)

  if (now && before && now.number === before.number && now.comments > before.comments) {
    $.ui.toast(`PR #${now.number}: ${now.comments - before.comments} new review comment(s)`)
  }

  await update($, pr, () => now)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    void poll($)
    $.clock.every(POLL_MS, () => void poll($))

    return next(e)
  })

  // A turn often pushes or opens the PR: don't wait for the timer.
  on('turn.complete', ($, e, next) => {
    void poll($)

    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const now = await read($, pr)

    if (e.props.hasSurvey || now === null) {
      return next(e)
    }

    const { Box, Text } = $.ui.resolve(e)
    const [label, color] = REVIEW[now.review] ?? ['No review yet', undefined]

    return (
      <Box>
        <Text wrap="truncate-end">
          <Text bold>PR #{now.number}</Text>
          <Text dimColor> {now.title} · </Text>
          <Text color={color}>
            {label} ({now.approvals})
          </Text>
          <Text dimColor> · checks </Text>
          <Text color="green">{now.pass}✓ </Text>
          <Text color={now.fail > 0 ? 'red' : undefined} dimColor={now.fail === 0}>
            {now.fail}✗{' '}
          </Text>
          <Text color={now.pending > 0 ? 'yellow' : undefined} dimColor={now.pending === 0}>
            {now.pending}…
          </Text>
          {now.hasConflict && <Text color="red"> · ⚠ merge conflicts</Text>}
        </Text>
      </Box>
    )
  })
}

